lib='''
def background(grid):
    """The most frequent color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def color_cells(grid, color):
    """All coordinates of cells of the given color, as (row, col) tuples."""
    return {(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color}

def runs(cells, color_of=None, minlen=2):
    """Maximal straight (horizontal or vertical) runs of length >= minlen from a set of coordinates."""
    res = []
    seen = set()
    def col(c):
        return color_of(c) if color_of else None
    for (i, j) in sorted(cells):
        if (i, j) in seen or (color_of and col((i, j)) != col((i, j))): pass
    # generic: group by color via runs within cells of equal value handled by caller
    for (i, j) in sorted(cells):
        if (i, j) in seen: continue
        for di, dj in ((0, 1), (1, 0)):
            if (i - di, j - dj) in cells: continue
            run = []
            k = 0
            while (i + k * di, j + k * dj) in cells:
                run.append((i + k * di, j + k * dj)); k += 1
            if len(run) >= minlen:
                res.append(run); seen |= set(run)
    return res

def color_runs(grid, color, minlen=3):
    """Maximal straight horizontal or vertical runs of the color with length >= minlen."""
    cells = color_cells(grid, color)
    res = []; seen = set()
    for (i, j) in sorted(cells):
        if (i, j) in seen: continue
        for di, dj in ((0, 1), (1, 0)):
            if (i - di, j - dj) in cells: continue
            run = []; k = 0
            while (i + k * di, j + k * dj) in cells:
                run.append((i + k * di, j + k * dj)); k += 1
            if len(run) >= minlen:
                res.append(run); seen |= set(run)
    return res

def ray(grid, r, c, dr, dc, color, out):
    """Fill out[r][c] then onward in direction (dr, dc) with color, stopping at the edge."""
    h, w = len(grid), len(grid[0])
    while 0 <= r < h and 0 <= c < w:
        out[r][c] = color; r += dr; c += dc

def toward(grid, cell, seg, out, color, blocked):
    """Fill cells from cell toward segment seg (exclusive of segment cells) in out; return True if any filled."""
    h, w = len(grid), len(grid[0])
    i, j = cell
    vertical = len({c[1] for c in seg}) == 1
    if vertical:
        lj = seg[0][1]; step = 1 if lj > j else -1
        k = j + step; path = []
        while 0 <= k < w and (i, k) not in blocked:
            path.append((i, k)); k += step
        if not path: out[i][lj] = color
    else:
        li = seg[0][0]; step = 1 if li > i else -1
        k = i + step; path = []
        while 0 <= k < h and (k, j) not in blocked:
            path.append((k, j)); k += step
        if not path: out[li][j] = color
    for (a, b) in path: out[a][b] = color
    return bool(path)

def project_to_lines(grid, out, cell, seg, lines, color):
    """From each other line, emit a ray of color at the position matching the cell's offset along seg."""
    h, w = len(grid), len(grid[0])
    vertical = len({c[1] for c in seg}) == 1
    pos = (cell[0] if vertical else cell[1]) - min((c[0] if vertical else c[1]) for c in seg)
    for o in lines:
        if o is seg: continue
        if len({c[1] for c in o}) == 1:
            oc = o[0][1]; r = min(c[0] for c in o) + pos
            ray(grid, r, oc + (1 if oc == 0 else -1), 0, 1 if oc == 0 else -1, color, out)
        else:
            orow = o[0][0]; c2 = min(c[1] for c in o) + pos
            ray(grid, orow + (1 if orow == 0 else -1), c2, 1 if orow == 0 else -1, 0, color, out)
